select
    cast(coalesce(est.qtde,0) as decimal(15,4)) -
    ((coalesce((select sum(qtde) as qtde from titemcompra ic inner join tcompra cmp on cmp.controle = ic.codcompra where cmp.datarecebimento > '01/31/2024'
        and ic.codproduto = est.controle and ic.confirmado= 'SIM' AND cmp.TIPOOPERACAO = '0' and cmp.movimentaestoque = 'SIM'),0) +
    coalesce((select sum(qtde) as qtde from titemordemproducao io inner join tordemproducao op on op.controle = io.codproducao where op.datafinal > '01/31/2024'
        and io.codproduto = est.controle and io.situacao = 'FINALIZADA'),0) +
    coalesce((select sum(qtdecomercial) as qtde from titensvendanfe inf inner join tvendanfe nf on nf.controle = inf.codnfe where nf.dataemissao > '01/31/2024'
        and inf.codproduto = est.controle and inf.cancelado <> 'SIM' AND nf.TIPOOPERACAO = '0' and enviada  = 'SIM'  and inf.movimentaestoque = 'SIM'
        and CODAPLICACAOPRODUTO <> '09' and ambiente = '1'),0))) +
    (coalesce((select sum(qtde) as qtde from titemvendaecf iec inner join tvendaecf ecf on ecf.controle = iec.codvendaecf where iec.dataecf > '01/31/2024'
        and iec.codproduto = est.controle  and iec.cancelado = 'NÃO'),0)  +
    coalesce((select sum(qtdecomercial) as qtde from titensvendanfe inf inner join tvendanfe nf on nf.controle = inf.codnfe where nf.dataemissao > '01/31/2024'
        and inf.codproduto = est.controle and inf.cancelado <> 'SIM' AND nf.TIPOOPERACAO = '1' and enviada  = 'SIM' and inf.movimentaestoque = 'SIM' and inf.codaplicacaoproduto <> '09' and inf.ambiente = '1'
        and inf.movimentaestoque = 'SIM' and CODAPLICACAOPRODUTO <> '09' and ambiente = '1'),0) +
    coalesce((select sum(qtde) as qtde from titemvendanfce infc inner join tvendanfce nfc on nfc.controle = infc.codnfce where nfc.dataemissao > '01/31/2024'
        and infc.codproduto = est.controle and infc.cancelado <> 'SIM' and infc.CODAPLICACAOPRODUTO <> '09' and infc.enviada = 'SIM' and infc.ambiente = '1'
        and infc.ambiente = '1'),0) +
    coalesce((select sum(qtde) as qtde from TITENNOTACONSUMIDOR inc inner join TNOTACONSUMIDOR nc on nc.controle = inc.CODNOTACONSUMIDOR where nc.dataemissao > '01/31/2024'
        and inc.codproduto = est.controle and inc.cancelado <> 'SIM' and inc.confirmado = 'SIM'),0) +
    coalesce((select sum(qtde) as qtde from titemopcomposicao iopc inner join tordemproducao op on op.controle = iopc.codproducao where op.datafinal > '01/31/2024'
        and iopc.codproduto = est.contr
ole and op.status = 'FINALIZADA'),0))
        - iif(coalesce((select sum(qtdealterada) as qtde from tajusteestoque where codproduto = est.controle and cast(datahoracadastro as date) >  '01/31/2024'),0) > 0,
        coalesce((select sum(qtdealterada) as qtde from tajusteestoque where codproduto = est.controle and cast(datahoracadastro as date) >  '01/31/2024'),0) * 1,
        coalesce((select sum(qtdealterada) as qtde from tajusteestoque where codproduto = est.controle and cast(datahoracadastro as date) >  '01/31/2024'),0))
    qtde_apuracao
from
    testoque est
where 
    est.controle = '502'
